parameters.jsCode:
const input = $('Workflow Input').first().json;
let applicable = [];
try { applicable = JSON.parse(input.applicable_slots_json || '[]'); } catch (e) { applicable = []; }
const byKey = {};
for (const s of applicable) { byKey[s.slot_key] = s; }

const raw = $input.first().json;
const parsed = (raw && typeof raw.output === 'object' && raw.output !== null) ? raw.output : raw;

const INTENTS = ['answering', 'question', 'request_human', 'booking_intent', 'decline_booking', 'chitchat', 'unclear'];
const intent = INTENTS.includes(parsed.intent) ? parsed.intent : 'unclear';

function coerce(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'object') return v;
  if (typeof v === 'number' || typeof v === 'boolean') return v;
  const s = String(v).trim();
  try { return JSON.parse(s); } catch (e) { return s; }
}

// Contact details end up on the lead record and in the mailing list, so a value
// that is not usable is dropped rather than stored: a wrong address looks like a
// contactable lead and is worse than an empty column. Character classes, not
// backslash escapes - a backslash does not reliably survive the JSON round trip
// this source goes through on every edit.
const EMAIL_RE = /^[a-z0-9._%+-]+@[a-z0-9-]+([.][a-z0-9-]+)*[.][a-z]{2,}$/;
const PHONE_SHAPE_RE = /^[+()0-9 .-]+$/;

function cleanEmail(rawValue) {
  if (typeof rawValue !== 'string') return null;
  const e = rawValue.trim().toLowerCase().replace(/^mailto:/, '');
  if (e.length < 6 || e.length > 254) return null;
  if (!EMAIL_RE.test(e)) return null;
  if (e.split('@')[0].length > 64) return null;
  return e;
}

function cleanPhone(rawValue) {
  if (typeof rawValue !== 'string') return null;
  const trimmed = rawValue.trim();
  if (!PHONE_SHAPE_RE.test(trimmed)) return null;
  const digits = trimmed.replace(/[^0-9]/g, '');
  // ITU E.164 caps a number at 15 digits; 7 is the shortest usable one.
  if (digits.length < 7 || digits.length > 15) return null;
  return trimmed;
}

function sanitiseContact(v) {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return v;
  const out = {};
  if (typeof v.full_name === 'string' && v.full_name.trim().length > 0) out.full_name = v.full_name.trim();
  const phone = cleanPhone(v.phone);
  const email = cleanEmail(v.email);
  if (phone) out.phone = phone;
  if (email) out.email = email;
  return out;
}

function isValid(def, v) {
  const t = def.value_type;
  if (t === 'enum') {
    if (typeof v !== 'string' || v.length === 0) return false;
    const choices = Array.isArray(def.choices) ? def.choices : null;
    if (choices && choices.length) return choices.indexOf(v) !== -1;
    return true;
  }
  if (t === 'text' || t === 'date') return typeof v === 'string' && v.length > 0;
  if (t === 'number') return typeof v === 'number' && isFinite(v);
  if (t === 'currency_range') {
    if (typeof v !== 'object' || v === null || Array.isArray(v)) return false;
    return (typeof v.min === 'number' && isFinite(v.min)) || (typeof v.max === 'number' && isFinite(v.max));
  }
  if (t === 'contact') {
    // sanitiseContact has already removed anything unusable, so a surviving
    // phone or email key is enough. A name on its own does not count.
    if (typeof v !== 'object' || v === null || Array.isArray(v)) return false;
    return typeof v.phone === 'string' || typeof v.email === 'string';
  }
  return false;
}

const cleaned = [];
const rawSlots = Array.isArray(parsed.slots) ? parsed.slots : [];
for (const s of rawSlots) {
  if (!s || typeof s.slot_key !== 'string') continue;
  const def = byKey[s.slot_key];
  if (!def) continue;
  const conf = typeof s.confidence === 'number' ? s.confidence : 0;
  if (conf < 0.6) continue;
  let v = coerce(s.value_json !== undefined ? s.value_json : s.value);
  if (def.value_type === 'currency_range' && v && typeof v === 'object' && !Array.isArray(v)) {
    const norm = {};
    if (typeof v.min === 'number') norm.min = v.min;
    if (typeof v.max === 'number') norm.max = v.max;
    norm.currency = (typeof v.currency === 'string' && v.currency) ? v.currency : 'AED';
    // The band is widened by ten percent either side so the catalogue search has
    // something to work with. That number is ours, not the lead's, and it must
    // never be read back to them - stated_text is what a human sees.
    if (typeof v.stated_text === 'string' && v.stated_text.trim()) norm.stated_text = v.stated_text.trim();
    v = norm;
  }
  if (def.value_type === 'contact') v = sanitiseContact(v);
  if (def.value_type === 'enum' && typeof v === 'number') v = String(v);
  if (!isValid(def, v)) continue;
  cleaned.push({ slot_key: s.slot_key, value: v, confidence: conf });
}

return [{ json: {
  ok: true,
  slots: cleaned,
  intent: intent,
  question_text: typeof parsed.question_text === 'string' ? parsed.question_text : '',
  is_repeat_of_previous: parsed.is_repeat_of_previous === true,
  language: (typeof parsed.language === 'string' && parsed.language) ? parsed.language : (input.language_hint || 'en'),
  unparseable: parsed.unparseable === true || (cleaned.length === 0 && intent === 'unclear')
} }];
